complete:
function RAONKUPLOAD_UploadComplete(uploadID) {
     // 삭제파일 리스트
     var deleteFileList = []
	 // 추가파일 리스트
	 var insertFileList = []

	  var jsonAll = RAONKUPLOAD.GetListInfo('json', uploadID);
      var jsonNew = jsonAll.newFile;
      var jsonDel = jsonAll.deleteFile;

      if( jsonNew){
    	 for(var i = 0; i < jsonNew.uploadPath.length; i++){
	    	 insertFileList.push({
	    		 fileSz : jsonNew.size[i]
	    	    ,fileExtsNm : jsonNew.extension[i]
	    	    ,phyFilePathNm : jsonNew.responseCustomValue[i].split("|")[0]
	    	    ,phyFileNm : jsonNew.responseCustomValue[i].split("|")[1]
	    	    ,lgcFileNm : jsonNew.originalName[i].substring( 0, jsonNew.originalName[i].lastIndexOf("."))
	    	 	,fileDvsnCd : jsonNew.customValue[i].split("|")[1]
	    	 });
	     }
     }

     if( jsonDel){
    	 for(var i = 0; i < jsonDel.uploadPath.length; i++){
    		 deleteFileList.push({
    			 fileGrpSn : jsonDel.customValue[i].split("|")[0]
	    	    ,fileSno :  jsonDel.customValue[i].split("|")[1]
	    	 });
	     }
     }

     // 파일업로드 완료여부 처리
     RAONKUPLOAD.CustomHandler[uploadID].isUploadComplete = true;
     RAONKUPLOAD.CustomHandler[uploadID].submit(insertFileList, deleteFileList);
}

