function RAONKUploadWrapper(opts){
	var config = "raonkupload.config.dev.xml";

	if (__APP__.baseUrl == 'https://www.smes.go.kr/venturein' || __APP__.baseUrl == 'http://real-bo.paas.smes-tipa.go.kr') {
		config = "raonkupload.config.prd.xml";
	} else if (__APP__.baseUrl == 'https://dev-venturein.paas.smes-tipa.go.kr/venturein' || __APP__.baseUrl == 'http://dev-bo.paas.smes-tipa.go.kr') {
		config = "raonkupload.config.dev_r.xml";
	}

	// 기본옵션
	var defaultOpts = {
		HandlerUrl: __APP__.context + '/file/raonkhandler',
		InitXml: config
		//InitXml: (__APP__.baseUrl == 'https://www.smes.go.kr/venturein' || __APP__.baseUrl == 'http://real-bo.paas.smes-tipa.go.kr') ? "raonkupload.config.prd.xml" : "raonkupload.config.dev.xml"
	};

	return new RAONKUpload(_.extend(defaultOpts, opts));
}

init:
function initUploader() {

        new RAONKUploadWrapper({
            Id : G_APLY_ATCH_UPLOADER_ID,
            Width : '100%',
            UploadHolder : 'aplyAtchFileUploadArea',
            DisableAlertMessage : { //confirm창을 표시하거나 숨기는 기능을 설정합니다.
                DisableDeleteConfirm : "1" // "1"로 설정시 파일 삭제시 confirm창 비활성.
            },
            SilentUpload : "0",//전송창 노출 여부를 설정합니다. "1"로 설정시 미노출입니다.
            MultiFileSelect : "0" // 파일선택창에서 단일 파일만 선택할 수 있도록 설정.
        });

        var allowExt = "jpg,jpeg,pptx,ppt,doc,docx,pdf,png,hwp,zip,hwpx";
        // type = T (태그방식), type = K( K업로더 방식)
        RAONKUPLOAD.CustomHandler = {
            APLY_ATCH_FILE : {
                type : "T",
                allowExt : allowExt,
                fileGrpSn : "",
                submit : function(insertFileList, deleteFileList) {

                    var formData = _AU.form.serializeObject("#form");
                    formData.insertFileList = insertFileList;
                    formData.deleteFileList = deleteFileList;

                    _AC.ajaxPost("/venturein/aply/v2/atch/save", formData, function(resultData) {

                        if (G_ATCH_SAVE_GBN == "SAVE") {
                            _AC.alert.open("저장되었습니다.", function() {
                                location.reload();
                            });
                        //[20240607송기범] 세션만료 자동저장 flag 추가
                        } else if(G_ATCH_SAVE_GBN == "sessExpAutoSAVE"){
                        	location.reload();
                        } else if(G_ATCH_SAVE_GBN == "SAVE_NEXT"){
                        	doNext('');
                        } else if (G_ATCH_SAVE_GBN == "CONFIRM") {
                            openAplyConfirmPop(resultData,true);
                        }
                    })
                }
            }
        }
    }
